export function mapMarkers(points,px,pz){const used=[];return points.map(p=>{const x=px(p.x),y=pz(p.z);let best={x:Math.max(18,Math.min(582,x)),y:Math.max(18,Math.min(432,y))};for(let k=0;k<150;k++){const r=k?Math.sqrt(k)*8:0,a=k*2.399,c={x:Math.max(18,Math.min(582,x+Math.cos(a)*r)),y:Math.max(18,Math.min(432,y+Math.sin(a)*r))};if(used.every(u=>Math.hypot(c.x-u.x,c.y-u.y)>31)){best=c;break;}}used.push(best);return{...p,mapX:best.x,mapY:best.y,anchorX:x,anchorY:y};});}

export function createPanels({campSafe,openEstate,navigate,getState,isInside,isAtShop,show,notify,changed,getWorld}){
 const $=id=>document.getElementById(id);
 const itemList=obj=>Object.entries(obj).map(([k,n])=>n+' × '+itemName(k)).join(', ');
 const heading=(title,text)=>'<span class="eyebrow">DEIN ALPENABENTEUER</span><h2>'+title+'</h2><p>'+text+'</p>';
 function run(action,redraw){const result=action();if(result.ok)changed();redraw(result.message);}
 function message(m){return m?'<p class="panel-message" role="status">'+m+'</p>':'';}
 function inventory(m=''){
  const s=getState(),inside=isInside();
  show(heading('Dein Rucksack',money(s.coins)+' · '+weight(s)+' / '+capacity(s)+' Plätze · Energie '+Math.round(s.energy)+' / 100')+message(m)+
  '<div class="item-grid">'+Object.entries(s.inventory).map(([k,n])=>'<article class="item-card"><span class="eyebrow">'+ITEMS[k][1]+'</span><h3>'+itemName(k)+' <b>×'+n+'</b></h3>'+(ITEMS[k][3]?'<p>Gibt bis zu '+ITEMS[k][3]+' Energie.</p><button data-eat="'+k+'" '+(s.energy>=100?'disabled':'')+'>Essen / trinken</button>':'')+(k==='boots'?'<p>Senkt den Energieverbrauch beim Rennen um ein Viertel.</p>':'')+(k==='backpack'?'<p>Verdoppelt deine Rucksackkapazität.</p>':'')+(k==='axe'?'<p>Verdoppelt die Ausbeute beim Fallholzsammeln.</p>':'')+(k==='stool'?'<p>Erhöht die kostenlose Erholung beim Rasten auf 40 Energie.</p>':'')+(k==='chest'?'<p>Erweitert dein Hüttenlager auf 100 Plätze.</p>':'')+(k==='lantern'?'<p>Beleuchtet bei Dämmerung und Nacht automatisch deine unmittelbare Umgebung.</p>':'')+(k==='lamp'?'<p>Leuchtet in Felsengang und Kristallgrotte automatisch, solange sie im Rucksack liegt.</p>':'')+(k==='pickaxe'?'<p>Ermöglicht den Abbau von Erz und Bergkristall.</p>':'')+(['rope','harness'].includes(k)?'<p>Benötigt an der Wasserfall-Querung und der Adlerwand. Die normalen Wanderwege bleiben frei begehbar.</p>':'')+(inside&&['autumnDecor','halloweenDecor','christmasDecor','christmasTree'].includes(k)?'<button data-decor="'+k+'">In der Wohnstube dekorieren</button>':'')+(inside?'<button data-store="'+k+'">Einlagern</button>':'')+'</article>').join('')+'</div>'+
  (!inside&&s.inventory.tent?'<button id="expedition-open">Bergzelt & Lagerfeuer</button>':'')+(inside?'<h3>Deine Lagertruhe</h3><p>Gegenstände bleiben über Nacht und nach dem Neuladen erhalten.</p><div class="item-grid">'+Object.entries(s.storage).map(([k,n])=>'<article class="item-card"><h3>'+itemName(k)+' ×'+n+'</h3><button data-take="'+k+'">Einpacken</button></article>').join('')+'</div><div class="actions"><button id="rest">Kostenlos rasten</button><button id="sleep">Eine Nacht schlafen</button><button id="workshop">Herstellen</button></div>':'<p>In der Alphütte findest du Lagertruhe, Werkplätze und kostenlose Erholung.</p>'));
  for(const el of document.querySelectorAll('[data-decor]'))el.onclick=()=>{s.home.seasonalDecor=el.dataset.decor;changed();inventory('Dekoration ausgewählt und gespeichert.');};
  for(const el of document.querySelectorAll('[data-eat]'))el.onclick=()=>run(()=>consume(s,el.dataset.eat),inventory);
  for(const el of document.querySelectorAll('[data-store]'))el.onclick=()=>run(()=>transfer(s,el.dataset.store,true,isInside()),inventory);
  for(const el of document.querySelectorAll('[data-take]'))el.onclick=()=>run(()=>transfer(s,el.dataset.take,false,isInside()),inventory);
  if(!inside&&s.inventory.tent)$('expedition-open').onclick=()=>expedition();if(inside){$('rest').onclick=()=>run(()=>rest(s,false,isInside()),inventory);$('sleep').onclick=()=>run(()=>rest(s,true,isInside()),inventory);$('workshop').onclick=()=>recipes();}
 }
 function expedition(m=''){const s=getState(),c=s.activities.camp;show(heading('Dein Berglager','Kleines Zelt, Fallholz und ein sicherer Platz neben dem Wanderweg.')+message(m)+'<p>Fallholz im Rucksack: '+(s.inventory.wood||0)+'</p><p>'+(c?'Lager in '+REGIONS[c.region].name+(c.fire?' · Feuer brennt.':' · Feuer aus.'):'Noch kein Lager aufgestellt.')+'</p><div class="actions"><button data-camp="pitch">Hier Zelt aufstellen</button><button data-camp="fire">Feuer machen · 2 Fallholz</button><button data-camp="sleep">Bis zum Morgen schlafen</button><button data-camp="pack">Feuer löschen & einpacken</button></div>');for(const b of document.querySelectorAll('[data-camp]'))b.onclick=()=>run(()=>expeditionAction(s,b.dataset.camp,campSafe?.()??false),expedition);}
 function recipes(station='kitchen',m=''){
  const s=getState(),inside=isInside();
  show(heading('Aus Funden wird Ausrüstung',inside?'Alle vier Arbeitsplätze stehen dir in der Alphütte zur Verfügung.':'Das Rezeptbuch kannst du überall lesen. Hergestellt wird in der Alphütte.')+message(m)+'<nav class="panel-tabs" aria-label="Arbeitsplätze">'+Object.entries(STATIONS).map(([k,v])=>'<button data-station="'+k+'" aria-pressed="'+(station===k)+'">'+v+'</button>').join('')+'</nav><div class="item-grid">'+RECIPES.filter(r=>r.station===station).map(r=>{
   const missing=Object.entries(r.ingredients).filter(([k,n])=>(s.inventory[k]||0)<n).map(([k,n])=>(n-(s.inventory[k]||0))+' × '+itemName(k));
   const available=inside&&!missing.length&&s.energy>=r.energy;
   return'<article class="item-card"><h3>'+r.name+'</h3><p>'+itemList(r.ingredients)+'</p><small>Ergibt '+itemList(r.output)+' · '+r.energy+' Energie</small><p class="missing">'+(!inside?'Arbeitsplatz: '+STATIONS[r.station]+' in der Alphütte.':missing.length?'Es fehlen: '+missing.join(', '):s.energy<r.energy?'Es fehlen '+Math.ceil(r.energy-s.energy)+' Energie.':'Alle Zutaten vorhanden.')+'</p><button data-craft="'+r.id+'" '+(!available?'disabled':'')+'>Herstellen</button></article>';
  }).join('')+'</div><button id="estate-workshop" class="primary">Alp & Weide ausbauen</button>');
  $('estate-workshop').onclick=()=>openEstate?.();
  for(const el of document.querySelectorAll('[data-station]'))el.onclick=()=>recipes(el.dataset.station);
  for(const el of document.querySelectorAll('[data-craft]'))el.onclick=()=>run(()=>craft(s,el.dataset.craft,isInside()?station:null),m=>recipes(station,m));
 }
 function shop(m='',stock=SHOP){
  const s=getState();show(heading('Der Dorfladen',money(s.coins)+' · Kaufe Vorräte und Werkzeuge oder verkaufe deine Funde. Ein Klick handelt ein Stück. Käsebedarf: Milch, Lab, Salz und Holz. Schokoladenbedarf: Portmann-Bohnen, Milch und Honig; für die vegane Variante Haferdrink und Zucker. Auch Baumaterial und Werkzeuge sind erhältlich.')+message(m)+'<h3>Einkaufen</h3><div class="item-grid">'+stock.map(k=>'<article class="item-card"><h3>'+itemName(k)+'</h3><p>'+money(ITEMS[k][2])+' · Im Rucksack: '+(s.inventory[k]||0)+'</p><button data-buy="'+k+'" '+(s.coins<ITEMS[k][2]||!isAtShop()?'disabled':'')+'>1 kaufen</button></article>').join('')+'</div><h3>Verkaufen</h3><div class="item-grid">'+Object.entries(s.inventory).filter(([k])=>sellPrice(k)>0).map(([k,n])=>'<article class="item-card"><h3>'+itemName(k)+' ×'+n+'</h3><p>'+money(sellPrice(k))+' je Stück</p><button data-sell="'+k+'" '+(!isAtShop()?'disabled':'')+'>1 verkaufen</button></article>').join('')+'</div><h3>Deine letzten Geldbewegungen</h3><ul class="ledger">'+s.ledger.slice(-10).reverse().map(e=>'<li>Tag '+e.day+' · '+(e.reason==='quest'?'Auftrag: '+QUESTS.find(q=>q.id===e.ref).name:e.reason==='meal'?'Restaurant: '+MEALS[e.ref].name:e.reason==='challenge'?(e.ref==='jass'?'Jass-Tagespreis':e.ref.startsWith('ski-')?'Ski-Prämie: '+SKI_LEVELS[e.ref.slice(4)].name:TARGET_NAMES[e.ref.split('-')[0]]+' · '+TARGET_LEVELS[e.ref.split('-')[1]].name):e.reason==='order'?'Dorfauftrag: '+ORDERS.find(o=>o.id===e.ref).name:e.reason==='treasure'?'Schatz: '+TREASURES.find(t=>t.id===e.ref).name:(e.reason==='buy'?'Kauf: ':'Verkauf: ')+itemName(e.ref))+' <strong>'+(e.delta>0?'+':'')+money(e.delta)+'</strong></li>').join('')+'</ul>');
  for(const el of document.querySelectorAll('[data-buy]'))el.onclick=()=>run(()=>trade(s,el.dataset.buy,'buy',isAtShop()),m=>shop(m,stock));
  for(const el of document.querySelectorAll('[data-sell]'))el.onclick=()=>run(()=>trade(s,el.dataset.sell,'sell',isAtShop()),m=>shop(m,stock));
 }
 function journal(m=''){
  const s=getState();show(heading('Dein Aufgabenbuch',(s.claimed.length+s.village.completed.length)+' / '+(QUESTS.length+ORDERS.length)+' Aufträge abgeschlossen · Tag '+s.day+'. Entdeckte Berggebiete: '+ADVENTURE_REGIONS.filter(k=>s.adventure.visited.includes(k)).length+' / 8.')+message(m)+'<h3>Das Dorf und seine Berggeschichte</h3><p>Sprich im Bergdorf mit Anna, Sepp, Ruth und Dani. Nimm Aufträge vor Ort an und kehre für die Übergabe zurück. Kein Zeitlimit.</p><div class="item-grid">'+orderCards(s)+'</div><h3>Deine weiteren Aufgaben</h3><div class="item-grid">'+QUESTS.map(q=>'<article class="item-card"><span class="eyebrow">'+(s.claimed.includes(q.id)?'BELOHNUNG ABGEHOLT':q.goal(s)?'ZIEL ERREICHT':'OFFEN')+'</span><h3>'+q.name+'</h3><p>'+q.text+'</p><p>Belohnung: '+money(q.reward)+'</p><button data-claim="'+q.id+'" '+(!q.goal(s)||s.claimed.includes(q.id)?'disabled':'')+'>Belohnung abholen</button></article>').join('')+'</div><h3>Sonnenalp-Slalom</h3><p>Der Start liegt auf der Sonnenalp. Ski und Helm werden gestellt. Pro Stufe gibt es eine einmalige Erfolgsprämie.</p><p>'+Object.entries(SKI_LEVELS).map(([id,l])=>l.name+': '+(s.ski.best[id]??'–')+' Punkte · '+s.ski.runs[id]+' Zielläufe'+(s.ski.completed.includes(id)?' · ✓ Prämie':'' )).join('<br>')+'</p><h3>Schneeball- und Vogelchallenge</h3>'+Object.entries(TARGET_NAMES).map(([kind,name])=>'<h4>'+name+'</h4><p>'+Object.entries(TARGET_LEVELS).map(([level,d])=>d.name+': '+(s.targets[kind].best[level]??'–')+' Punkte · '+s.targets[kind].runs[level]+' Runden'+(s.targets[kind].completed.includes(level)?' · ✓ Prämie':'')).join('<br>')+'</p>').join('')+'<h3>Jass im Bergrestaurant</h3><p>'+s.jass.wins+' Siege / '+s.jass.runs+' Runden · Bestwert '+s.jass.best+' von 3 Stichen. Tagespreis CHF 15.00 höchstens einmal pro Spieltag.'+(s.jass.prizeDay===s.day?' Heute bereits erhalten.':'')+'</p><h3>Melanies Retro-Spiele</h3>'+Object.entries(ARCADE_GAMES).map(([kind,g])=>'<p><b>'+g.name+'</b><br>'+Object.entries(ARCADE_LEVELS).map(([level,l])=>l.name+': '+(s.arcade.best[kind+'-'+level]||0)+' Punkte · '+(s.arcade.runs[kind+'-'+level]||0)+' Runden').join('<br>')+'</p>').join('')+'<h3>Deine Entdeckungen</h3><p>'+s.adventure.visited.map(k=>REGIONS[k].name).join(' · ')+'</p>'+Object.values(LANDMARKS).filter(l=>s.adventure.discoveries.includes(l.id)).map(l=>'<details><summary>'+l.title+'</summary><p>'+l.text+'</p></details>').join('')+'<h3>Deine Kletterrouten</h3><p>'+Object.values(CLIMBS).map(c=>(s.climbing.completed.includes(c.id)?'✓ ':'○ ')+c.name+(s.climbing.best[c.id]!==undefined?' · '+s.climbing.best[c.id]+' Punkte':'')).join('<br>')+'</p><h3>Unterwegs auf der Alp</h3><p>Fallholz, Fasern, Beeren, Pilze und Blüten findest du rund um die Wege. Die Spitzhacke vom Dorfladen erschliesst Erz und Kristall im nordöstlichen Hang. Nach einer Nacht gibt es neuen Sammelnachschub.</p><p>Automatisches Speichern läuft auf diesem Gerät. Über Einstellungen kannst du eine Spielstanddatei sichern und auf einem anderen Gerät wieder laden.</p>');
  for(const el of document.querySelectorAll('[data-claim]'))el.onclick=()=>run(()=>claimQuest(s,el.dataset.claim),journal);
 }
 function map(){
  const s=getState(),id=s.position.region||'alp',world=getWorld?.(),visited=new Set(s.adventure.visited),known=new Set(visited);
  for(const g of GATEWAYS)if(visited.has(g.from)&&(!g.secret||s.adventure.secretOpen))known.add(g.to);
  const unique=GATEWAYS.filter(g=>Object.keys(REGIONS).indexOf(g.from)<Object.keys(REGIONS).indexOf(g.to)&&known.has(g.from)&&known.has(g.to)&&(!g.secret||s.adventure.secretOpen));
  const graph='<svg class="world-map" viewBox="0 0 600 340" role="img" aria-label="Verbindungen zwischen den entdeckten Gebieten"><rect width="600" height="340" rx="16" fill="#e6eadb"/>'+unique.map(g=>'<line x1="'+REGIONS[g.from].map[0]+'" y1="'+REGIONS[g.from].map[1]+'" x2="'+REGIONS[g.to].map[0]+'" y2="'+REGIONS[g.to].map[1]+'" stroke="#b4a17b" stroke-width="4"/>').join('')+Object.entries(REGIONS).filter(([k])=>known.has(k)).map(([k,r],i)=>'<circle cx="'+r.map[0]+'" cy="'+r.map[1]+'" r="'+(k===id?9:6)+'" fill="'+(k===id?'#a88242':visited.has(k)?'#395c4a':'#aab99d')+'"/><text x="'+r.map[0]+'" y="'+(r.map[1]+20)+'" text-anchor="middle">'+(i+1)+'</text>').join('')+'</svg>';
  const bounds=world?.colliders?.bounds||REGIONS[id].bounds||[-37,37,-30,29],px=x=>(x-bounds[0])/(bounds[1]-bounds[0])*600,pz=z=>(z-bounds[2])/(bounds[3]-bounds[2])*450;
  const paths=(world?.paths||[]).map(p=>p.points);
  const points=id==='alp'?[{name:'Alphütte',x:-16,z:-3.25},{name:'Heuunterstand',...HOF.kiosk.entry},{name:'Jonny',x:6,z:3},{name:'Heuwiese',...HAY_FIELD.entry},{name:'See-Ruheplatz',...POND_CAMP.entry},{name:'Kornfeld · 160 m²',x:-19,z:8},{name:'Anbaupläne · Bohnen',...HOF.fields.cocoa.entry},{name:'Aussicht',x:17,z:-20.2}]:[];
  if(id==='alp'){for(const a of Object.values(ANIMALS).filter(a=>a.id!=='jonny'))points.push({name:a.name,...animalPoint(s,a.id)});for(const p of Object.values(FARM_POINTS))points.push(p);}
  if(id==='city')points.push(PORTMANN_STORE);if(id==='village')points.push(...(world?.interactive||[]).filter(n=>n.fodderShop||n.villageService));
  if(id==='pasture')points.push({name:'Jonny',x:6,z:3},{name:'Grundparcours',x:-19,z:14});
  if(id==='arcadeshop')points.push(ARCADE_START,MELANIE);
  if(id==='restaurant')points.push(JASS_TABLE,RESTAURANT_COUNTER);
  if(id===SKI_START.region)points.push(SKI_START);
  for(const point of Object.values(TARGET_STARTS).filter(p=>p.region===id))points.push(point);
  for(const n of Object.values(VILLAGERS).filter(n=>n.region===id))points.push({name:n.name+' · '+n.role,x:n.x,z:n.z});
  for(const c of Object.values(CLIMBS).filter(c=>c.region===id))points.push({name:c.name,x:c.entry[0],z:c.entry[1]});
  for(const g of GATEWAYS.filter(g=>g.from===id&&(!g.secret||s.adventure.secretOpen)))points.push({name:REGIONS[g.to].name,x:g.x,z:g.z});
  const local='<svg class="alp-map" viewBox="0 0 600 450" role="img" aria-label="Lokale Wege und Spielerposition"><rect width="600" height="450" rx="20" fill="#dce5cd"/>'+paths.map(p=>'<polyline points="'+p.map(([x,z])=>px(x)+','+pz(z)).join(' ')+'" fill="none" stroke="#b5a17d" stroke-width="10"/>').join('')+(id==='alp'?'<ellipse cx="'+px(HOF.pond.x)+'" cy="'+pz(HOF.pond.z)+'" rx="39" ry="26" fill="#86b8be"/>':id==='see'?'<ellipse cx="'+px(12)+'" cy="'+pz(-4)+'" rx="89" ry="76" fill="#86b8be"/>':id==='schlucht'?'<rect x="0" y="'+pz(-2.5)+'" width="600" height="38" fill="#86b8be"/>':'')+mapMarkers(points,px,pz).map((p,i)=>'<g><title>'+p.name+'</title><line x1="'+p.anchorX+'" y1="'+p.anchorY+'" x2="'+p.mapX+'" y2="'+p.mapY+'" stroke="#725337"/><circle cx="'+p.mapX+'" cy="'+p.mapY+'" r="14" fill="#725337"/><text x="'+p.mapX+'" y="'+(p.mapY+7)+'" text-anchor="middle" style="font: bold 20px sans-serif;fill:white">'+(i+1)+'</text></g>').join('')+'<circle cx="'+px(s.position.x)+'" cy="'+pz(s.position.z)+'" r="9" fill="#264e43" stroke="white" stroke-width="3"/><text x="'+(px(s.position.x)+12)+'" y="'+(pz(s.position.z)+20)+'">Du'+(isInside()?' · in der Hütte':'')+'</text><text x="20" y="25">N ↑</text></svg>';
  show(heading(id==='alp'?'Karte der Portmann-Alp':REGIONS[id].name,REGIONS[id].text)+'<h3>Dein Weg durch die Bergwelt</h3>'+graph+'<ol class="map-legend">'+Object.entries(REGIONS).filter(([k])=>known.has(k)).map(([k,r])=>'<li>'+r.name+'</li>').join('')+'</ol><h3>Wege vor Ort</h3>'+local+'<ol class="map-legend">'+points.map(p=>'<li>'+p.name+'</li>').join('')+'</ol><h3>Zu Fuss ein Wegziel wählen</h3><p>Deine Figur folgt dem Weg bis zum Eingang. Keine Schnellreise. Verborgene Verbindungen erscheinen erst nach ihrer Entdeckung.</p><div class="actions">'+(!isInside()?(world?.interactive||[]).filter(n=>(n.gateway||n.id==="hut"||n.barnDoor||n.portmannStore||n.cozyActivity||n.forestDiscovery||n.hayStorage||n.hayField||n.pondCamp||n.fodderShop||n.villageService||n.downhill||n.hutSleep||n.mountainGuide||n.valleyView||n.id==='lookout')&&(!n.secret||s.adventure.secretOpen)).map(n=>'<button data-walk="'+n.id+'">'+n.name+'</button>').join(''):'<p>Verlasse zuerst die Alphütte, um einen Weg zu wählen.</p>')+'</div>');for(const el of document.querySelectorAll('[data-walk]'))el.onclick=()=>navigate?.(el.dataset.walk);
 }
 return{inventory,recipes,shop,journal,map};
}
